def is_irreducible(p):
    """Ben-Or irreducibility test for GF(2)[x]."""
    n = p_deg(p)
    if n <= 0:
        return False
    if n == 1:
        return True

    # Condition 1: p must divide x^(2^n) + x
    # i.e., x^(2^n) ≡ x (mod p)
    x_pow = p_powmod(2, 1 << n, p)
    if p_mod(p_add(x_pow, 2), p) != 0:
        return False

    # Condition 2: no roots in proper subfields GF(2^(n/d))
    def prime_divisors(m):
        res, d = [], 2
        while d * d <= m:
            if m % d == 0:
                res.append(d)
                while m % d == 0:
                    m //= d
            d += 1
        if m > 1:
            res.append(m)
        return res

    for d in prime_divisors(n):
        exp = 1 << (n // d)
        x_pow = p_powmod(2, exp, p)
        to_check = p_add(x_pow, 2)
        if p_gcd(p, to_check) != 1:
            return False
    return True

